'use strict';
// Learning routes extend the existing workspace and its version-2 backups.
let reviewOnly=false,practiceStarted=Date.now();
const originalRender=render,originalPractice=practice,originalProgress=progress,originalReport=showReport;
const sourceOfficial='https://www.etec.gov.sa/ar/programs/mustaqbalhum';
const tips={
 'الحساب':['ابدأ بالعمليات الأساسية','رتّب العمليات: الأقواس ثم الضرب والقسمة ثم الجمع والطرح. قدّر الناتج قبل اختيار الإجابة.','في الزيادة ثم الخصم، احسب كل نسبة من قيمتها الجديدة، وليس من السعر الأصلي.'],
 'النسب والتناسب':['حوّل النسبة إلى أجزاء','اجمع أجزاء النسبة، ثم اقسم الإجمالي عليها. اضرب قيمة الجزء في عدد الأجزاء المطلوبة.','عند التناسب العكسي، زيادة أحد المقدارين تقلّل الآخر؛ لا تستخدم التناسب الطردي آليًا.'],
 'الجبر':['اكتب المعادلة أولًا','حدّد المجهول، فك الأقواس، واجمع الحدود المتشابهة. طبّق العملية نفسها على طرفي المعادلة.','عوّض الناتج في المعادلة الأصلية للتحقق من صحة الحل.'],
 'الهندسة':['ارسم وحدّد المعطيات','ميّز بين المحيط والمساحة. اكتب القانون، ثم عوّض بالقيم مع التأكد من الوحدات.','الشكل المرسوم لا يكفي لإثبات تساوي الأطوال أو الزوايا دون معطيات.'],
 'الإحصاء':['ميّز بين مقاييس البيانات','المتوسط = مجموع القيم ÷ عددها. رتّب القيم لإيجاد الوسيط؛ والمنوال هو الأكثر تكرارًا.','في سؤال قيمة مفقودة، استخرج المجموع من المتوسط والعدد أولًا.'],
 'الاحتمال':['احصر النتائج الممكنة','في الحالات المتساوية الإمكان: الاحتمال = عدد الحالات المطلوبة ÷ جميع الحالات.','السحب دون إرجاع يغيّر عدد العناصر في السحب التالي.'],
 'المعدل والعمل والزمن':['وحّد الوحدات قبل الحساب','المسافة = السرعة × الزمن. في العمل المشترك، اجمع معدلات الإنجاز لا أزمنة الإنجاز.','حوّل الدقائق إلى ساعات إذا كانت السرعة بالساعة.'],
 'المقارنة الكمية':['قارن دون افتراضات إضافية','استخدم المعطيات وحدها. إن أمكن، جرّب قيمًا موجبة وسالبة وصفرًا ضمن القيود.','إذا تغيّرت العلاقة باختلاف القيم المسموحة، فالمعطيات غير كافية للحسم.'],
 'التناظر اللفظي':['صِف العلاقة في جملة','حدّد علاقة الكلمتين واتجاهها: جزء وكل، أداة ووظيفة، أو سبب ونتيجة. طبّق الجملة على كل خيار.','تشابه المعنى وحده لا يكفي؛ المطلوب تشابه العلاقة واتجاهها.'],
 'إكمال الجمل':['اقرأ الجملة كاملة','انتبه لأدوات الربط والنفي والاستدراك. توقّع المعنى قبل تجربة الخيارات، ثم اقرأ الجملة بالخيار كاملًا.','الخيار المقبول لغويًا قد لا ينسجم مع معنى الجملة.'],
 'الخطأ السياقي':['ابحث عن تناقض المعنى','اقرأ الجملة كوحدة واحدة. حدّد الكلمة التي تعارض السياق، ثم جرّب معنى بديلًا يصلح الجملة.','المقصود خطأ المعنى في السياق، وليس مجرد خطأ نحوي أو إملائي.'],
 'استيعاب المقروء':['استدل من النص','ميّز بين الفكرة الرئيسة والتفصيل. ارجع إلى العبارة الداعمة، وفرّق بين التصريح والاستنتاج.','لا تستبدل دليل النص بمعلومة من خارج النص، ولا تعمّم أكثر مما يسمح به.'],
 'الارتباط والاختلاف':['حدّد معيار المجموعة','سمِّ العلاقة المشتركة بين الكلمات، ثم ابحث عن الكلمة التي لا تنتمي وفق المعيار نفسه.','اختبر المعيار على جميع الكلمات؛ لا تعتمد على انطباع أولي.']
};
function uniqueQuestions(list){const seen=new Set();return list.filter(q=>{const k=q.text.trim()+'|'+[...q.options].sort().join('|');if(seen.has(k))return false;seen.add(k);return true})}
function mixedOptions(q){const copy=clone(q),indices=shuffle([0,1,2,3]);copy.options=indices.map(i=>q.options[i]);copy.answer=indices.indexOf(q.answer);return copy}
function skillStats(){const groups=new Map();for(const q of data.questions)if(!groups.has(q.category))groups.set(q.category,{name:q.category,section:q.section,n:0,c:0,ids:new Set()});for(const h of history){const g=groups.get(h.category);if(g){g.n++;g.c+=Number(h.correct);g.ids.add(h.id)}}return [...groups.values()].map(g=>({...g,percent:g.n?Math.round(g.c/g.n*100):null})).sort((a,b)=>(a.percent??-1)-(b.percent??-1))}
function reviewItems(now=Date.now()){const grouped=new Map();for(const h of history){if(!grouped.has(h.id))grouped.set(h.id,[]);grouped.get(h.id).push(h)}return data.questions.flatMap(q=>{const h=grouped.get(q.id);if(!h?.length||!h.some(x=>!x.correct))return [];let streak=0;for(let i=h.length-1;i>=0&&h[i].correct;i--)streak++;const days=streak===0?0:streak===1?1:streak===2?3:streak===3?7:14;const latest=h.at(-1),due=Date.parse(latest.at)+days*86400000;return [{q,streak,due,dueNow:due<=now}]})}
function trainSkill(name,review=false){reviewOnly=review;section='الكل';category=name||'الكل';difficulty='الكل';question=null;pick();go('practice')}
pick=function(){pool=uniqueQuestions(questionBank().filter(q=>(section==='الكل'||q.section===section)&&(category==='الكل'||q.category===category)&&(difficulty==='الكل'||q.difficulty===difficulty)));if(reviewOnly){const ids=new Set(reviewItems().filter(r=>r.dueNow).map(r=>r.q.id));pool=pool.filter(q=>ids.has(q.id))}const tried=new Set(history.map(h=>h.id)),unseen=pool.filter(q=>!tried.has(q.id)),alternate=pool.filter(q=>q.id!==question?.id);const available=unseen.length?unseen:alternate.length?alternate:pool;question=available.length?mixedOptions(available[Math.floor(Math.random()*available.length)]):null;selected=null;checked=false;practiceStarted=Date.now()};
practice=function(){originalPractice();const card=$('#main .workspace .card');if(!card)return;const intro=document.createElement('div');intro.className='study-strip';intro.innerHTML=`<span>${reviewOnly?'مراجعة مستحقة من أخطائك':'تدريب مهاري · الخيارات تتغيّر لتتدرّب على الفهم'}</span><button id="study-method">طريقة الحل</button>${reviewOnly?'<button id="all-practice">العودة إلى التدريب العام</button>':''}`;card.prepend(intro);$('#study-method').onclick=()=>{go('lessons');if(question)$('#lesson-filter').value=question.category;renderLessonList(question?.category)};$('#all-practice')?.addEventListener('click',()=>trainSkill());if(checked&&question){const reflection=document.createElement('details');reflection.innerHTML='<summary>ثبّت فهمك قبل السؤال التالي</summary><p>اشرح لنفسك: لماذا هذه الإجابة صحيحة؟ ما الخطوة التي غيّرت فهمك؟ كيف تتأكد من الناتج أو دليل النص؟</p>';card.appendChild(reflection)}if(reviewOnly&&!question){const empty=card.querySelector('.empty');if(empty)empty.textContent='أنهيت المراجعات المستحقة ضمن هذا الاختيار. عد غدًا أو ابدأ تدريبًا عامًا.'}};
function home(){const due=reviewItems().filter(r=>r.dueNow).length,goal=settings.goal||10,today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Riyadh'}),done=history.filter(h=>h.status!=='blank'&&new Date(h.at).toLocaleDateString('en-CA',{timeZone:'Asia/Riyadh'})===today).length,skills=skillStats(),weak=skills.filter(g=>g.ids.size>=5&&g.percent<70).slice(0,3),diagnosed=attempts.some(a=>a.name==='تشخيص البداية');$('#main').innerHTML=title('خطتك اليوم','ابدأ من مستواك الحالي، وافهم الحل، ثم اختبر نفسك.')+`<section class="daily-card"><div><span class="tag">هدف اليوم</span><h2>${num(done)} من ${num(goal)} إجابة</h2><p>جلسة قصيرة منتظمة، ثم مراجعة سبب الخطأ.</p><div class="progress-track"><span style="width:${Math.min(100,done/goal*100)}%"></span></div></div><label>عدد الإجابات اليوم<select id="daily-goal">${[10,20,30].map(n=>`<option value="${n}" ${goal===n?'selected':''}>${num(n)} سؤالًا</option>`).join('')}</select></label></section><div class="learning-path"><section class="card"><span class="step-label">١ · حدّد البداية</span><h2>${diagnosed?'أعد قياس مستواك':'تشخيص البداية'}</h2><p>٢٠ سؤالًا: ١٠ لفظي و١٠ كمي خلال ٢٥ دقيقة تدريبية. لقطة أولية، لا حكم نهائي على مستواك.</p><button class="primary" id="diagnose">ابدأ التشخيص</button></section><section class="card"><span class="step-label">٢ · افهم وتدرّب</span><h2>تأسيس المهارات</h2><p>طريقة حل، مثال مشروح، ثم سؤال مستقل تحاول حله بنفسك.</p><button id="learn-start">اختر مهارة</button></section><section class="card"><span class="step-label">٣ · ثبّت ما تعلّمته</span><h2>${num(due)} مراجعة مستحقة</h2><p>راجع الأخطاء والأسئلة المتروكة الآن، ثم بعد نجاحك بفواصل ١، ٣، ٧، و١٤ يومًا.</p><button id="due-start" ${due?'':'disabled'}>ابدأ المراجعة</button></section><section class="card"><span class="step-label">٤ · تدرب على الوقت</span><h2>محاكاة تدريبية</h2><p>اختبار قصير أو جلسة طويلة بأقسام مؤقّتة، ثم تقرير وخطة مراجعة.</p><button id="simulate">اختر الاختبار</button></section></div><section class="card spaced"><h2>أين تركز اليوم؟</h2>${weak.length?weak.map(g=>`<div class="skill-row"><div><b>${esc(g.name)}</b><p>${num(g.percent)}٪ في المحاولة الأولى · ${num(g.ids.size)} أسئلة مختلفة</p></div><button data-focus="${esc(g.name)}">تدرّب</button></div>`).join(''):'<p>أكمل التشخيص أو خمسة أسئلة مختلفة على الأقل في المهارة لتظهر أولوية تدريب مبنية على نتائجك.</p>'}<p class="muted">النسبة من الإجابة الأولى لكل سؤال بصيغته الحالية. الإعادة تُعرض منفصلة في صفحة تقدّمك. النسبة ليست درجة قياس.</p></section>`;$('#daily-goal').onchange=e=>{settings.goal=+e.target.value;save();home()};$('#diagnose').onclick=()=>startLearningExam('diagnostic');$('#learn-start').onclick=()=>go('lessons');$('#due-start').onclick=()=>trainSkill(null,true);$('#simulate').onclick=()=>go('exams');document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>trainSkill(b.dataset.focus))}
function lessons(){$('#main').innerHTML=title('افهم الطريقة، ثم طبّق','اختر مهارة. حاول في المثال قبل فتح الشرح، ثم طبّق على سؤال آخر.')+`<section class="card"><label>المهارة<select id="lesson-filter">${Object.keys(tips).map(n=>`<option>${esc(n)}</option>`).join('')}</select></label><div id="lesson-content"></div></section>`;$('#lesson-filter').onchange=e=>renderLessonList(e.target.value);renderLessonList($('#lesson-filter').value||Object.keys(tips)[0])}
function renderLessonList(name){if(!$('#lesson-content'))return;const t=tips[name]||['افهم المطلوب','حدّد المعطيات واقرأ جميع الخيارات.','راجع الدليل أو عوّض الناتج.'],list=uniqueQuestions(questionBank().filter(q=>q.category===name)),q=list.find(q=>q.difficulty==='سهل')||list[0];$('#lesson-content').innerHTML=`<div class="lesson-intro"><span class="tag">${esc(name)}</span><h2>${esc(t[0])}</h2><p>${esc(t[1])}</p><p class="pitfall"><b>انتبه:</b> ${esc(t[2])}</p></div>${q?`<article class="worked-example"><h3>مثال من بنكك</h3><p class="qtext">${esc(q.text)}</p><ul>${q.options.map(o=>`<li>${esc(o)}</li>`).join('')}</ul><details><summary>حاول أولًا، ثم افتح الحل</summary><p><b>الإجابة:</b> ${esc(q.options[q.answer])}</p><p>${esc(q.explanation)}</p><p class="muted">اسأل نفسك: أي معطى استخدمته؟ وكيف استبعدت الخيارات الأخرى؟</p></details></article><button id="apply-skill" class="primary">طبّق على سؤال آخر</button>`:'<p>لا توجد أسئلة لهذه المهارة.</p>'}`;$('#apply-skill')?.addEventListener('click',()=>{trainSkill(name);if(question?.id===q.id&&list.length>1){question=mixedOptions(list.find(x=>x.id!==q.id));practice()}})}
function reviewPage(){const list=reviewItems().sort((a,b)=>a.due-b.due),due=list.filter(r=>r.dueNow);$('#main').innerHTML=title('الأخطاء والمتروك، فرصة للتعلّم','حاول مجددًا من دون عرض الإجابة. النجاح يؤجّل المراجعة التالية، والخطأ يعيدها الآن.')+`<section class="card"><h2>${num(due.length)} مستحقة الآن · ${num(list.length-due.length)} مجدولة لاحقًا</h2><p>جدول المراجعة اقتراح تدريبي. عد إلى المثال المشروح إذا تكرر الخطأ.</p><button id="review-due" class="primary" ${due.length?'':'disabled'}>راجع المستحق الآن</button></section><div class="grid spaced">${list.slice(0,100).map(r=>`<section class="card"><span class="tag">${r.dueNow?'حان وقت المراجعة':new Date(r.due).toLocaleDateString('ar-SA')}</span><h3>${esc(r.q.category)}</h3><p>${esc(r.q.text.slice(0,160))}${r.q.text.length>160?'…':''}</p><p class="muted">${num(r.streak)} إجابات صحيحة متتالية</p></section>`).join('')||'<section class="card"><h2>لا توجد أخطاء أو أسئلة متروكة للمراجعة</h2><p>ابدأ التدريب أو التشخيص لتكوين قائمة مراجعتك.</p></section>'}</div>`;$('#review-due').onclick=()=>trainSkill(null,true)}
exams=function(){const reviewed=data.questions.filter(isReviewed).length;$('#main').innerHTML=title('اختبر فهمك وإدارة وقتك','اختر البنك ووضع الاختبار. الحلول تظهر بعد تسليم المحاولة.')+`<section class="card"><h2>إعدادات الاختبار</h2><div class="filters"><label>بنك الأسئلة<select id="bank-scope"><option value="reviewed">المراجع تحريريًا فقط (${num(reviewed)})</option><option value="all">البنك الكامل مع الإضافات غير المراجعة</option></select></label><label class="inline-check"><input type="checkbox" id="strict-mode" ${settings.strict!==false?'checked':''}> محاكاة صارمة: إغلاق الدروس والحلول حتى التسليم</label></div><p class="muted">المراجعة تحريرية داخلية وليست اعتمادًا رسميًا. يُستخدم الاختيار نفسه في التدريب والدروس. الأسئلة المستوردة لا تُعتبر مراجعة تلقائيًا.</p></section><div class="grid spaced"><section class="card"><h2>تشخيص البداية</h2><p>٢٠ سؤالًا · ٢٥ دقيقة · ١٠ لفظي و١٠ كمي</p><button class="primary" data-profile="diagnostic">ابدأ التشخيص</button></section><section class="card"><h2>اختبار متجدد</h2><p>٦٠ سؤالًا · ٧٥ دقيقة · ٣٠ لفظي و٣٠ كمي</p><button class="primary" data-profile="standard">ابدأ الاختبار</button></section><section class="card"><h2>محاكاة الأقسام القابلة للتخصيص</h2><p>الإعداد الافتراضي: ٥ أقسام × ٢٤ سؤالًا × ٢٥ دقيقة؛ ١٢٠ سؤالًا و١٢٥ دقيقة. توزيع افتراضي متوازن بين اللفظي والكمي.</p><div class="filters"><label>عدد الأقسام<select id="sim-blocks">${[3,4,5,6].map(n=>`<option value="${n}" ${n===(settings.simBlocks||5)?'selected':''}>${num(n)}</option>`).join('')}</select></label><label>أسئلة القسم<select id="sim-size">${[10,20,24,30].map(n=>`<option value="${n}" ${n===(settings.simSize||24)?'selected':''}>${num(n)}</option>`).join('')}</select></label><label>دقائق القسم<select id="sim-minutes">${[10,15,20,25,30].map(n=>`<option value="${n}" ${n===(settings.simMinutes||25)?'selected':''}>${num(n)}</option>`).join('')}</select></label><label>نسبة اللفظي<select id="sim-verbal">${[50,55,75].map(n=>`<option value="${n}" ${n===(settings.simVerbal||50)?'selected':''}>${num(n)}٪</option>`).join('')}</select></label></div><p id="sim-total" role="status"></p><p>التنقل داخل القسم الحالي فقط. يُغلق القسم عند الانتقال أو انتهاء وقته. المؤقّت يستمر عند إغلاق الصفحة، ووقت الانقطاع يظهر منفصلًا في التقرير.</p><button class="primary" data-profile="sectioned">ابدأ المحاكاة</button></section><section class="card"><h2>قبل أن تبدأ</h2><p>هذه إعدادات تدريب تختارها، وليست توثيقًا لصيغة اختبار قياس الحالية. طابق العدد والمدة والتوزيع مع تعليمات اختبارك وحجزك؛ قد تختلف باختلاف نوع الاختبار.</p><ul><li>جهّز ورقة للمسودة ومكانًا هادئًا.</li><li>راجع الأسئلة المعلّمة قبل إغلاق القسم.</li><li>لا تمثل النسبة هنا درجة معيارية أو توقعًا لدرجة قياس.</li></ul><a href="${sourceOfficial}" target="_blank" rel="noopener">المعلومات الرسمية للهيئة</a></section></div><details class="card spaced"><summary>النماذج الثابتة الخمسة للمقارنة</summary><p>تبقى الأسئلة والخيارات ثابتة. تكرار النموذج قد يقيس التذكر؛ قارن أيضًا أداءك على أسئلة جديدة.</p><div class="actions">${Object.keys(data.tests).map(n=>`<button data-fixed="${esc(n)}">${esc(n)}</button>`).join('')}</div></details>`;$('#bank-scope').value=settings.bankScope==='all'?'all':'reviewed';$('#bank-scope').onchange=e=>{settings.bankScope=e.target.value;question=null;save()};$('#strict-mode').onchange=e=>{settings.strict=e.target.checked;save()};const update=()=>{settings.simBlocks=+$('#sim-blocks').value;settings.simSize=+$('#sim-size').value;settings.simMinutes=+$('#sim-minutes').value;settings.simVerbal=+$('#sim-verbal').value;$('#sim-total').textContent=`المجموع: ${num(settings.simBlocks*settings.simSize)} سؤالًا · ${num(settings.simBlocks*settings.simMinutes)} دقيقة`;save()};for(const id of ['sim-blocks','sim-size','sim-minutes','sim-verbal'])$('#'+id).onchange=update;$('#sim-total').textContent=`المجموع: ${num((settings.simBlocks||5)*(settings.simSize||24))} سؤالًا · ${num((settings.simBlocks||5)*(settings.simMinutes||25))} دقيقة`;document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>startLearningExam(b.dataset.profile));document.querySelectorAll('[data-fixed]').forEach(b=>b.onclick=()=>startExam(b.dataset.fixed,'fixed'))};

function balancedQuestions(n){const previous=new Set(attempts.filter(a=>a.mode==='random').at(-1)?.qs.map(q=>q.id)||[]);const choose=s=>{const count=typeof n==='number'?n:n[s==='لفظي'?'verbal':'quant'];const all=uniqueQuestions(questionBank().filter(q=>q.section===s));if(all.length<count)throw Error('عدد الأسئلة المختلفة غير كافٍ في قسم '+s);const groups=shuffle([...new Set(all.map(q=>q.category))]).map(c=>[...shuffle(all.filter(q=>q.category===c&&!previous.has(q.id))),...shuffle(all.filter(q=>q.category===c&&previous.has(q.id)))]);const out=[];while(out.length<count){for(const group of groups){if(group.length&&out.length<count)out.push(group.shift())}}return out};return {verbal:choose('لفظي'),quant:choose('كمي')}}
freshQuestions=function(){const q=balancedQuestions(30);return shuffle([...q.verbal,...q.quant]).map(mixedOptions)};
function startLearningExam(profile){if(exam){go('exams');return}if(!['diagnostic','standard','sectioned'].includes(profile))throw Error('إعداد اختبار غير صالح');try{const blocks=[3,4,5,6].includes(settings.simBlocks)?settings.simBlocks:5,size=[10,20,24,30].includes(settings.simSize)?settings.simSize:24,minutesPerBlock=[10,15,20,25,30].includes(settings.simMinutes)?settings.simMinutes:25,ratio=[50,55,75].includes(settings.simVerbal)?settings.simVerbal:50,total=profile==='diagnostic'?20:profile==='sectioned'?blocks*size:60,verbal=profile==='sectioned'?Math.round(total*ratio/100):total/2,q=balancedQuestions({verbal,quant:total-verbal});let qs=[];if(profile==='sectioned'){let v=0,k=0;for(let b=0;b<blocks;b++){const needV=Math.round((b+1)*verbal/blocks)-v,needK=size-needV;qs.push(...shuffle([...q.verbal.slice(v,v+needV),...q.quant.slice(k,k+needK)]));v+=needV;k+=needK}}else qs=shuffle([...q.verbal,...q.quant]);qs=qs.map(mixedOptions);const now=Date.now(),minutes=profile==='diagnostic'?25:profile==='sectioned'?blocks*minutesPerBlock:75;exam={id:uid(),name:profile==='diagnostic'?'تشخيص البداية':profile==='sectioned'?'محاكاة الأقسام التدريبية':'اختبار متجدد',mode:'random',strict:settings.strict!==false,bankScope:settings.bankScope==='all'?'all':'reviewed',timerModel:2,unobservedSeconds:0,qs:clone(qs),answers:Array(qs.length).fill(null),times:Array(qs.length).fill(0),flags:Array(qs.length).fill(false),index:0,startedAt:now,deadline:now+minutes*60000,lastTouch:now,...(profile==='sectioned'?{profile,block:0,blockCount:blocks,blockSize:size,blockMinutes:minutesPerBlock,blockDeadline:now+minutesPerBlock*60000}:{})};save();activate('exams');renderExam();runTimer()}catch(err){alert('تعذّر بدء الاختبار: '+err.message)}}

const originalRenderExam=renderExam,originalJump=jump,originalSetAnswer=setExamAnswer;
function syncBlocks(){if(!exam||exam.profile!=='sectioned')return;while(exam&&Date.now()>=exam.blockDeadline){if(exam.block===5){finishExam('timeout');return}const boundary=exam.blockDeadline;const elapsed=Math.max(0,boundary-exam.lastTouch);exam.times[exam.index]+=elapsed/1000;exam.block++;exam.index=exam.block*20;exam.blockDeadline+=25*60000;exam.lastTouch=boundary;save()}}
remaining=function(){if(!exam)return '0:00';const sec=Math.max(0,Math.ceil(((exam.profile==='sectioned'?exam.blockDeadline:exam.deadline)-Date.now())/1000));return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`};
jump=function(index){syncBlocks();if(!exam)return;if(exam.profile==='sectioned'&&(index<exam.block*20||index>=(exam.block+1)*20))return;originalJump(index)};
setExamAnswer=function(value){const id=exam?.id,index=exam?.index;syncBlocks();if(exam&&exam.id===id&&exam.index===index)originalSetAnswer(value)};
renderExam=function(){syncBlocks();if(!exam)return;originalRenderExam();if(exam.profile==='sectioned'){const e=exam,start=e.block*20,end=start+20;$('#prev').disabled=e.index===start;$('#next').disabled=e.index===end-1;document.querySelectorAll('[data-jump]').forEach(b=>{const i=+b.dataset.jump;if(i<start||i>=end)b.remove()});const bar=document.createElement('div');bar.className='study-strip';bar.innerHTML=`<b>القسم ${num(e.block+1)} من ٦ · ${esc(e.qs[start].section)} · الوقت لهذا القسم</b><button id="next-block">${e.block===5?'إنهاء الاختبار':'إغلاق القسم والانتقال للتالي'}</button>`;$('#main .card').prepend(bar);$('#next-block').onclick=()=>{if(!confirm('سيُغلق القسم الحالي ولن تستطيع العودة إليه. هل تريد المتابعة؟'))return;if(e.block===5){finishExam();return}touchExam();e.block++;e.index=e.block*20;e.blockDeadline=Math.min(e.deadline,Date.now()+25*60000);save();renderExam()}}};
runTimer=function(){clearInterval(timer);timer=setInterval(()=>{if(!exam)return;if(Date.now()>=exam.deadline){finishExam('timeout');return}const b=exam.block;syncBlocks();if(!exam)return;if(b!==exam.block&&view==='exams')renderExam();if($('#time'))$('#time').textContent=remaining();if(Math.floor(Date.now()/1000)%10===0){touchExam();save()}},1000)};
showReport=function(id){originalReport(id);const e=attempts.find(a=>a.id===id);if(!e)return;const low=breakdown(e,'category').filter(g=>g.percent<70).slice(0,3),panel=document.createElement('section');panel.className='card spaced';panel.innerHTML=`<h2>خطوتك التالية بعد النتيجة</h2><p>افهم خطأك، ثم جرّب سؤالًا جديدًا في المهارة نفسها، وعد للمراجعة لاحقًا.</p><div class="actions">${low.map(g=>`<button data-report-train="${esc(g.key)}">تدريب ${esc(g.key)}</button>`).join('')}<button id="report-review">جدول مراجعة الأخطاء والمتروك</button></div><p class="muted">النتيجة وصف لهذه المحاولة؛ لا تتنبأ بدرجة اختبار القدرات. المهارات ذات الأسئلة القليلة تحتاج محاولات إضافية.</p>`;$('#main .report-actions').after(panel);document.querySelectorAll('[data-report-train]').forEach(b=>b.onclick=()=>trainSkill(b.dataset.reportTrain));$('#report-review').onclick=()=>go('review')};
progress=function(){originalProgress();const panel=document.createElement('section');panel.className='card spaced';panel.innerHTML=`<h2>هل تحسّنك قائم على أسئلة مختلفة؟</h2><p>الدقة تشمل التكرار. قارنها بعدد الأسئلة المختلفة، وأعد الاختبار بمجموعة جديدة.</p><div class="table-wrap"><table><thead><tr><th>المهارة</th><th>المحاولات</th><th>أسئلة مختلفة</th><th>مؤشر التدريب</th></tr></thead><tbody>${skillStats().map(g=>`<tr><th>${esc(g.name)}</th><td>${num(g.n)}</td><td>${num(g.ids.size)}</td><td>${g.ids.size<5?'عينة غير كافية':g.percent<70?'تحتاج مراجعة':'واصل التثبيت'}</td></tr>`).join('')}</tbody></table></div></section>`;$('#main').appendChild(panel)};
render=function(){if(view==='home')home();else if(view==='lessons')lessons();else if(view==='review')reviewPage();else originalRender()};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{if(reviewOnly){reviewOnly=false;question=null}go(b.dataset.view)});
