const originalReferences=references;
references=function(){originalReferences();const card=document.createElement('section');card.className='card spaced';const texts=new Set(data.questions.map(q=>q.text.trim()));card.innerHTML=`<h2>مصادر التعلم وحدود البنك</h2><p><a href="audit-batch-01.html" target="_blank" rel="noopener">تقرير الدفعة الأولى — الأسئلة ١–١٠٠</a></p><p><a href="audit-batch-02.html" target="_blank" rel="noopener">تقرير الدفعة الثانية — الأسئلة ١٠١–٢٠٠</a></p><p><a href="audit-batch-03.html" target="_blank" rel="noopener">تقرير الدفعة الثالثة — الأسئلة ٢٠١–٣٠٠</a></p><p><a href="audit-batch-04.html" target="_blank" rel="noopener">تقرير الدفعة الرابعة — الأسئلة ٣٠١–٤٠٠</a></p><p><a href="audit-batch-05.html" target="_blank" rel="noopener">تقرير الدفعة الخامسة — الأسئلة ٤٠١–٥٠٠</a></p><p><a href="audit-batch-06.html" target="_blank" rel="noopener">تقرير الدفعة السادسة — الأسئلة ٥٠١–٦٠٠</a></p><p><a href="audit-batch-07.html" target="_blank" rel="noopener">تقرير الدفعة السابعة — الأسئلة ٦٠١–٧٠٠</a></p><p><a href="audit-batch-08.html" target="_blank" rel="noopener">تقرير الدفعة الأخيرة — الأسئلة ٧٠١–١٠٠٠</a></p><p>البنك الحالي: ${num(data.questions.length)} سجلًا و${num(texts.size)} نص سؤال مختلفًا. النص المتكرر قد يخدم أسئلة مختلفة إذا تغيرت الخيارات؛ لذلك يستبعد التدريب والاختبار المتجدد تطابق النص والخيارات معًا.</p><p>مفاتيح الإجابات الأصلية تتبع نمطًا منتظمًا؛ يتغيّر ترتيب الخيارات في التدريب والاختبار المتجدد مع إبقاء التصحيح صحيحًا. النماذج الثابتة تبقى للمقارنة.</p><p>رُوجع ${num(window.GAT_BASE.editorialReview?.reviewedCount||0)} سؤال تحريرياً ومنطقياً؛ بقي ${num(window.GAT_BASE.editorialReview?.remainingCount??1000)} سؤال خارج الدفعات المكتملة. الصعوبة تقدير تحريري يحتاج معايرة بنتائج الطلاب. نسبة الإجابات الصحيحة مؤشر تدريبي فقط. لا تعرض المنصة درجة معيارية أو توقعًا لدرجة قياس.</p><ul><li><a href="${sourceOfficial}" target="_blank" rel="noopener">هيئة تقويم التعليم والتدريب: مستقبلهم والتدريب على القدرات</a> — يركز التعريف على القدرة التحليلية والاستدلالية.</li><li><a href="https://ies.ed.gov/ncee/wwc/PracticeGuide/1" target="_blank" rel="noopener">دليل IES لتنظيم التعلم</a> — التعلم المتباعد، والاسترجاع، والتناوب بين المثال المحلول والتطبيق.</li></ul><p class="muted">جدول المراجعة ١، ٣، ٧، ١٤ يومًا اختيار تنظيمي للمنصة، وليس جدولًا مفروضًا في الدليل. تفاصيل المحاكاة إعدادات تدريبية تحتاج مطابقة دليل اختبارك الحالي.</p>`;$('#main').prepend(card)};
